"""JSONRPC server implementations."""

import asyncio
import itertools
import logging
import typing
import weakref

from jsilib import _utils
from jsilib.aio.interface import IReactor
from jsilib.jsi import exc as jsi_exc
from jsilib.jsi import helpers as jsi_helpers
from jsilib.jsi.api import IJSIAcceptor, IJSIConnection, IJSIMessage, JSIBytesMessage

from . import _globals
from .interface import IJSONRPCNotifier, IJSONRPCServer, IMethodHandlerContext, IMethodHandlerRegistry
from .messages import SID, JSONRPCError, JSONRPCMessage, JSONRPCNotif, JSONRPCRequest, JSONRPCResponse
from .namespace import Namespace

__all__ = export = _utils.ExportList()

_next_connection_id = itertools.count(1)

logger = logging.getLogger(_globals.LOGGER_NAME)


@export
class JSONRPCServer(IJSONRPCServer):
    """Implementation of the JSONRPC server.

    :param reactor:
        Reactor to be used.

    :param acceptor:
        JSI protocol acceptor to be used to accept incoming connections.
    """

    def __init__(self, reactor: IReactor, acceptor: IJSIAcceptor):
        self._reactor = reactor
        self._acceptor = acceptor
        self._globals = {}
        self._root_namespace = Namespace()
        self._active_connection_tasks = []
        self._active_connections: typing.Dict[int, IJSIConnection] = {}
        self._closed = False

    @property
    def globals(self) -> dict:
        """Access user-defined placeholder for server globals.

        Initially, this is an empty dict, but can be modified by the user to
        pass some non request related data to method handlers (which can access
        this dict via :attr:`IMethodHandlerContext.globals` property).

        Use this to pass things like database connections, configuration options
        and other things that are known or created along with the server, will
        not change for as long as the server lives and otherwise would be hard
        to pass to method handlers.
        """
        return self._globals

    def is_closed(self) -> bool:
        return self._closed

    async def close(self):
        if not self._closed:
            self._closed = True
            logger.debug('[%s] Closing the server...', _utils.get_obj_addr(self))
            for task in self._active_connection_tasks:
                await task.cancel()
            logger.info('[%s] The server has been closed.', _utils.get_obj_addr(self))

    def list_methods(self) -> typing.Iterator[typing.Tuple[str, IMethodHandlerRegistry.MethodHandlerType]]:
        return iter(self._root_namespace.list_methods())

    def list_namespaces(self) -> typing.Iterator[typing.Tuple[str, 'IMethodHandlerRegistry']]:
        return iter(self._root_namespace.list_namespaces())

    def find_method(self, name: str) -> typing.Optional[IMethodHandlerRegistry.MethodHandlerType]:
        return self._root_namespace.find_method(name)

    def register_method(self, name: str, handler: IMethodHandlerRegistry.MethodHandlerType):
        self._root_namespace.register_method(name, handler)

    def register_namespace(self, ns: 'IMethodHandlerRegistry', prefix: str = None):
        self._root_namespace.register_namespace(ns, prefix=prefix)

    async def notify(self, method: str, params: typing.Any = None, sid: SID = None, body: IJSIMessage = None):

        def create_payload(body: IJSIMessage) -> IJSIMessage:
            notif = JSONRPCMessage(JSONRPCNotif(method=method, params=params, sid=sid), body=body)
            return notif.dump()

        async def send_payload(cached, connection):
            body = await cached.acquire()
            async with body:
                await connection.send(create_payload(body))

        logger.info(
            '[%s] Sending notification to all connected clients: method=%r, params=%r, sid=%r, body=%r',
            _utils.get_obj_addr(self), method, params, sid, body
        )
        if body is None or body.size() == 0:
            connections = (c for c in dict(self._active_connections).values())
            await asyncio.gather(*[c.send(create_payload(JSIBytesMessage(b''))) for c in connections])
        else:
            cached = await jsi_helpers.create_cached_message(self._reactor, body)
            async with cached:
                connections = (c for c in dict(self._active_connections).values())
                await asyncio.gather(*[send_payload(cached, c) for c in connections])

    async def serve_forever(self):
        """Run server forever.

        Once this method is executed, server is starting to accept incoming
        connections and handlig requests.
        """

        @_utils.log_exceptions(logger)
        async def handle_connection(connection: IJSIConnection):

            async def handle_request(request: JSONRPCMessage[JSONRPCRequest]) -> JSONRPCMessage[JSONRPCResponse]:
                method_name = request.head.method
                method_handler = self._root_namespace.find_method(method_name)
                if method_handler is None:
                    return JSONRPCMessage(
                        JSONRPCResponse.from_request(request.head, error=JSONRPCError.method_not_found(method_name))
                    )
                try:
                    response = await method_handler(
                        self._MethodHandlerContext(self, connection, request, self._globals)
                    )
                except Exception as e:
                    logger.error('[%s] An exception was raised:', _utils.get_obj_addr(self), exc_info=True)
                    return JSONRPCMessage(
                        JSONRPCResponse.from_request(request.head, error=JSONRPCError.internal_error(str(e)))
                    )
                if not isinstance(response, JSONRPCMessage):
                    response = JSONRPCMessage(JSONRPCResponse.from_request(request.head, result=response))
                return response

            async def try_handle_request(request: JSONRPCMessage[JSONRPCRequest]) -> IJSIMessage:
                try:
                    response = await handle_request(request)
                    return response.dump()
                except Exception as e:
                    logger.error('[%s] An exception was raised:', _utils.get_obj_addr(connection), exc_info=True)
                    return JSONRPCMessage(
                        JSONRPCResponse.from_request(request.head, error=JSONRPCError.internal_error(str(e)))
                    ).dump()

            connection_id = next(_next_connection_id)
            logger.info(
                '[%s] Client connected - awaiting messages... (%s)', _utils.get_obj_addr(self),
                _utils.get_obj_addr(connection)
            )
            self._active_connections[connection_id] = connection
            try:
                async with connection:
                    while not connection.is_closed():
                        message = await JSONRPCMessage.load(await connection.recv())
                        logger.debug('[%s] < %r', _utils.get_obj_addr(connection), message)
                        if isinstance(message.head, JSONRPCRequest):
                            await connection.send(await try_handle_request(message))
                        else:
                            raise NotImplementedError('TODO: implement unexpected message handling (if needed)')
            except jsi_exc.ConnectionClosedError:
                pass
            finally:
                del self._active_connections[connection_id]
                logger.info(
                    '[%s] Client disconnected (%s). Remaining active connections: %d', _utils.get_obj_addr(self),
                    _utils.get_obj_addr(connection), len(self._active_connections)
                )

        while not self.is_closed():
            try:
                connection = await self._acceptor.accept()
            except jsi_exc.AcceptorClosedError:
                return
            else:
                task = self._reactor.run(handle_connection(connection))
                self._active_connection_tasks.append(task)

    class _MethodHandlerContext(IMethodHandlerContext):

        def __init__(
            self, server: 'JSONRPCServer', connection: IJSIConnection, request: JSONRPCMessage[JSONRPCRequest],
            globals: dict
        ):
            self._server = server
            self._connection = weakref.ref(connection)
            self._request = request
            self._globals = globals

        @property
        def server_notifier(self) -> IJSONRPCNotifier:
            return self._server

        @property
        def connection_notifier_factory(self) -> typing.Callable[[], typing.Optional[IJSONRPCNotifier]]:

            def factory() -> typing.Optional[IJSONRPCNotifier]:
                connection = self._connection()
                if connection is None or connection.is_closed():
                    return None
                return self._ConnectionProxy(connection, self._server)

            return factory

        @property
        def globals(self) -> dict:
            return self._globals

        @property
        def request(self) -> JSONRPCMessage[JSONRPCRequest]:
            return self._request

        class _ConnectionProxy(IJSONRPCNotifier):

            def __init__(self, target: IJSIConnection, server: 'JSONRPCServer'):
                self._target = target
                self._server = server

            async def notify(self, method: str, params: typing.Any = None, sid: SID = None, body: IJSIMessage = None):
                notif = JSONRPCNotif(method=method, params=params, sid=sid)
                if body is None or body.size() == 0:
                    await self._target.send(JSONRPCMessage(notif, body=body).dump())
                else:
                    cached = await jsi_helpers.create_cached_message(self._server._reactor, body)
                    async with cached:
                        message = await cached.acquire()
                        async with message:
                            await self._target.send(JSONRPCMessage(notif, body=body).dump())
